  /// Turns SDK logging on and configures it. Logging is OFF by default — this
  /// SDK reports nothing until you call this (or construct the client with a
  /// [ClientConfig] whose logging is enabled). Reports go to the endpoint this
  /// build was generated with, or to the `endpoint` you pass; with neither,
  /// nothing is sent. Pass `enabled: false` to turn logging back off.
  LoggingConfig setLoggingConfig({
    bool? enabled,
    String? endpoint,
    String? apiKey,
    String? environment,
    String? release,
    Map<String, dynamic>? user,
    Map<String, dynamic>? tags,
    bool? filterPii,
  }) {
    final logging = _config.logging ??= LoggingConfig();
    if (endpoint != null) logging.endpoint = endpoint;
    if (apiKey != null) logging.apiKey = apiKey;
    if (environment != null) logging.environment = environment;
    if (release != null) logging.release = release;
    if (user != null) logging.user = user;
    if (tags != null) logging.tags = tags;
    if (filterPii != null) logging.filterPii = filterPii;
    logging.enabled = enabled ?? true;
    return logging;
  }

